const choices={finish:['oak','walnut','dark'],fabric:['linen','sage','clay'],room:['warm','light'],stage:['room','object'],lighting:['day','golden','evening']};
export function readState(search,products){const q=new URLSearchParams(search);const product=Object.hasOwn(products,q.get('product'))?q.get('product'):'290';const p=products[product];const variant=p.variants.find(v=>v.key===q.get('variant'))?.key||p.variants[0].key;const state={product,variant,dimensions:q.get('dimensions')==='1'};for(const[k,values]of Object.entries(choices))state[k]=values.includes(q.get(k))?q.get(k):values[0];for(const[k,min,max]of [['x',-1,1],['z',-.5,1],['rotation',0,360]]){const n=Number(q.get(k));state[k]=Number.isFinite(n)?Math.max(min,Math.min(max,n)):0;}return state;}
export function stateQuery(state){const q=new URLSearchParams();for(const[k,v]of Object.entries(state))q.set(k,k==='dimensions'?(v?'1':'0'):String(v));return q.toString();}
